/* Real-card data from the bilinear and modulate diagnostics on a PCI Rage Pro (1002:4750, BIOS 113-41902-106,
 * ATI3DCIF 4.11.2692 mip-disable bug patched), 640x480 at 32 bpp, dither off, no perspective correction. Do not edit.
 *
 * A group is one frame. Texture format 0 RGB565, 1 ARGB1555, 2 ARGB4444, 4 CI8, 5 CI4, 6 RGB332, 7 ARGB8888. lo and hi
 * are the two texel colours: native channel values for formats 0 to 2 and 6, 8 bit values for 7, and for the palettised
 * formats the 24 bit colours the card returned for palette entries 0 and 1 (it quantises a palette entry to 565).
 * secondary 1: the texture is the composite (second) texture of a modulate composite over a solid white primary and
 * white vertex colour; 0: the primary texture.
 *
 * Strip groups (kind 0: columns alternate lo, hi; kind 1: rows alternate) are drawn magnified 128 pixels per texel with
 * the quad corners on whole pixels and the texture coordinates in texels.
 *
 * Ramp groups (kind 4, formats 0 to 2, secondary 1) are a modulate composite with the primary a solid 565 texture
 * (prim, native channel values) and the diffuse colour dif (0xRRGGBB): one row of 64 columns per quad, 8 pixels each,
 * point sampled, column c showing secondary texel c, whose channels are (c & 31, c & 63, 31 - (c & 31)) in 565,
 * (c & 31, (7 c) & 31, 31 - (c & 31)) in 1555 and (c & 15, (3 c) & 15, 15 - (c & 15)) in 4444. The probe is the middle
 * of the column. */
struct mod_probe {
    unsigned short x, y;
    unsigned       rgb;
};
struct mod_quad {
    int      x0, y0, x1, y1;
    double   u0, v0, u1, v1;
    int      kind, count, first;
    int      prim[3];
    unsigned dif;
};
struct mod_group {
    const char                 *name;
    int                         format, secondary, lo[3], hi[3], nquad;
    const struct mod_quad      *quads;
};
